#include <bits/stdc++.h>
using namespace std;

struct Bridges {
    vector<int> tin, low, par, pe, it, bridge, from, to;
    int timer = 0;
    Bridges(int n, const vector<pair<int, int>> &edges) {
        vector<vector<pair<int, int>>> g(n);
        for (int i = 0; i < (int)edges.size(); ++i) {
            auto [u, v] = edges[i];
            g[u].push_back({v, i});
            g[v].push_back({u, i});
        }
        tin.assign(n, -1);
        low.resize(n);
        par.assign(n, -1);
        pe.assign(n, -1);
        it.assign(n, 0);
        bridge.assign(edges.size(), 0);
        from.assign(edges.size(), -1);
        to.resize(edges.size());
        for (int root = 0; root < n; ++root)
            if (tin[root] < 0) {
                vector<int> st{root};
                tin[root] = low[root] = timer++;
                while (!st.empty()) {
                    int u = st.back();
                    if (it[u] < (int)g[u].size()) {
                        auto [v, e] = g[u][it[u]++];
                        if (e == pe[u])
                            continue;
                        if (tin[v] < 0) {
                            par[v] = u;
                            pe[v] = e;
                            from[e] = u;
                            to[e] = v;
                            tin[v] = low[v] = timer++;
                            st.push_back(v);
                        } else {
                            low[u] = min(low[u], tin[v]);
                            if (tin[v] < tin[u]) {
                                from[e] = u;
                                to[e] = v;
                            }
                        }
                    } else {
                        st.pop_back();
                        if (par[u] >= 0) {
                            int p = par[u];
                            low[p] = min(low[p], low[u]);
                            if (low[u] > tin[p])
                                bridge[pe[u]] = 1;
                        }
                    }
                }
            }
    }
};
struct DSU {
    vector<int> p, sz;
    DSU(int n) : p(n), sz(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (x != p[x]) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    int join(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return x;
        if (sz[x] < sz[y])
            swap(x, y);
        p[y] = x;
        sz[x] += sz[y];
        return x;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<pair<int, int>> edges(m);
    for (auto &[u, v] : edges) {
        cin >> u >> v;
        --u;
        --v;
    }
    Bridges b(n, edges);
    DSU ds(n);
    for (int i = 0; i < m; ++i)
        if (!b.bridge[i])
            ds.join(edges[i].first, edges[i].second);
    vector<vector<int>> g(n);
    for (int i = 0; i < m; ++i)
        if (b.bridge[i]) {
            int u = ds.find(edges[i].first),
                v = ds.find(edges[i].second);
            g[u].push_back(v);
            g[v].push_back(u);
        }
    auto far = [&](int root) {
        vector<int> d(n, -1);
        queue<int> q;
        q.push(root);
        d[root] = 0;
        int best = root;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            if (d[u] > d[best])
                best = u;
            for (int v : g[u])
                if (d[v] < 0) {
                    d[v] = d[u] + 1;
                    q.push(v);
                }
        }
        return pair<int, int>{best, d[best]};
    };
    cout << far(far(ds.find(0)).first).second << '\n';
}

