int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i)
        cin >> a[i];
    int q;
    cin >> q;
    vector<vector<pair<int, int>>> queries(n + 1);
    for (int i = 0, l, r; i < q; ++i) {
        cin >> l >> r;
        queries[r].push_back({l, i});
    }
    int b = 1;
    while (b < n)
        b *= 2;
    const int INF = 1000000000;
    vector<pair<int, int>> t(2 * b, {INF, 0});
    auto put = [&](int i, int prev) {
        int p = b + i - 1;
        t[p] = {prev, i};
        for (p /= 2; p; p /= 2)
            t[p] = min(t[p * 2], t[p * 2 + 1]);
    };
    unordered_map<int, int> last;
    vector<int> ans(q);
    for (int r = 1; r <= n; ++r) {
        int old = last[a[r]];
        if (old)
            put(old, INF);
        put(r, old);
        last[a[r]] = r;
        for (auto [l, id] : queries[r]) {
            int L = b + l - 1, R = b + r;
            pair<int, int> res{INF, 0};
            while (L < R) {
                if (L & 1)
                    res = min(res, t[L++]);
                if (R & 1)
                    res = min(res, t[--R]);
                L /= 2;
                R /= 2;
            }
            ans[id] = res.first < l ? a[res.second] : 0;
        }
    }
    for (int x : ans)
        cout << x << '\n';
}

