struct Range {
    int n;
    vector<long long> mn, mx, lazy;
    Range(vector<long long> a)
        : n(a.size()), mn(4 * n), mx(4 * n), lazy(4 * n) {
        build(1, 0, n - 1, a);
    }
    void pull(int p) {
        mn[p] = min(mn[p * 2], mn[p * 2 + 1]);
        mx[p] = max(mx[p * 2], mx[p * 2 + 1]);
    }
    void apply(int p, long long v) {
        mn[p] += v;
        mx[p] += v;
        lazy[p] += v;
    }
    void push(int p) {
        if (lazy[p]) {
            apply(p * 2, lazy[p]);
            apply(p * 2 + 1, lazy[p]);
            lazy[p] = 0;
        }
    }
    void build(int p, int l, int r, vector<long long> &a) {
        if (l == r) {
            mn[p] = mx[p] = a[l];
            return;
        }
        int m = (l + r) / 2;
        build(p * 2, l, m, a);
        build(p * 2 + 1, m + 1, r, a);
        pull(p);
    }
    void add(int p, int l, int r, int L, int R, long long v) {
        if (R < l || r < L)
            return;
        if (L <= l && r <= R) {
            apply(p, v);
            return;
        }
        push(p);
        int m = (l + r) / 2;
        add(p * 2, l, m, L, R, v);
        add(p * 2 + 1, m + 1, r, L, R, v);
        pull(p);
    }
    long long get(int p, int l, int r, int L, int R) {
        if (R < l || r < L)
            return LLONG_MAX;
        if (L <= l && r <= R)
            return mn[p];
        push(p);
        int m = (l + r) / 2;
        return min(get(p * 2, l, m, L, R),
                   get(p * 2 + 1, m + 1, r, L, R));
    }
    void add(int l, int r, long long v) {
        add(1, 0, n - 1, l, r, v);
    }
    long long get(int l, int r) {
        return get(1, 0, n - 1, l, r);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    vector<pair<int, int>> s(m);
    vector<vector<int>> start(n), finish(n + 1);
    for (int i = 0, l, r; i < m; ++i) {
        cin >> l >> r;
        --l;
        --r;
        s[i] = {l, r};
        start[l].push_back(i);
        finish[r + 1].push_back(i);
    }
    Range seg(a);
    long long best = -1;
    int at = 0;
    for (int i = 0; i < n; ++i) {
        for (int id : finish[i])
            seg.add(s[id].first, s[id].second, 1);
        for (int id : start[i])
            seg.add(s[id].first, s[id].second, -1);
        long long value = seg.mx[1] - seg.mn[1];
        if (value > best) {
            best = value;
            at = i;
        }
    }
    vector<int> chosen;
    for (int i = 0; i < m; ++i)
        if (s[i].first <= at && at <= s[i].second)
            chosen.push_back(i + 1);
    cout << best << '\n' << chosen.size() << '\n';
    for (int id : chosen)
        cout << id << ' ';
}

#include <bits/stdc++.h>
using namespace std;

struct Euler {
    vector<int> tin, tout, par, depth, order, sz;
    Euler(const vector<vector<int>> &g, int root = 1)
        : tin(g.size()), tout(g.size()), par(g.size(), -1),
          depth(g.size()), sz(g.size(), 1) {
        vector<int> st{root};
        par[root] = root;
        depth[root] = root == 0 ? 0 : 1;
        while (!st.empty()) {
            int u = st.back();
            st.pop_back();
            tin[u] = order.size();
            order.push_back(u);
            for (int v : g[u])
                if (v != par[u]) {
                    par[v] = u;
                    depth[v] = depth[u] + 1;
                    st.push_back(v);
                }
        }
        for (int i = (int)order.size() - 1; i >= 0; --i) {
            int u = order[i];
            tout[u] = tin[u] + sz[u] - 1;
            if (u != root)
                sz[par[u]] += sz[u];
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> g(n + 1);
    for (int i = 1, u, v; i < n; ++i) {
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    Euler e(g);
    vector<long long> f(n + 1);
    for (int u = 1; u <= n; ++u)
        f[1] += e.depth[u];
    long long ans = f[1];
    for (int u : e.order)
        if (u != 1) {
            f[u] = f[e.par[u]] + n - 2LL * e.sz[u];
            ans = max(ans, f[u]);
        }
    cout << ans << '\n';
}

