    const int V = 500000, B = 700;
    vector<long long> a(V + 1);
    vector<vector<long long>> sum(B + 1);
    for (int b = 1; b <= B; ++b)
        sum[b].resize(b);
    int q;
    cin >> q;
    while (q--) {
        int t, x, y;
        cin >> t >> x >> y;
        if (t == 1) {
            a[x] += y;
