                ans = sum[x][y];
            else
                for (int i = y; i <= V; i += x)
                    ans += a[i];
            cout << ans << '\n';
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, p, k;
    cin >> n >> p >> k;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    vector<vector<long long>> s(n, vector<long long>(p));
    for (auto &row : s)
        for (auto &x : row)
            cin >> x;
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(),
         [&](int x, int y) { return a[x] > a[y]; });
    int M = 1 << p;
    vector<int> bits(M);
    for (int m = 1; m < M; ++m)
        bits[m] = bits[m >> 1] + (m & 1);
    const long long NEG = -(1LL << 60);
    vector<long long> dp(M, NEG), ndp(M);
    dp[0] = 0;
    for (int i = 0; i < n; ++i) {
        int x = order[i];
        fill(ndp.begin(), ndp.end(), NEG);
        for (int mask = 0; mask < M; ++mask)
            if (dp[mask] != NEG) {
                ndp[mask] = max(
                    ndp[mask],
                    dp[mask] + (i - bits[mask] < k ? a[x] : 0));
                for (int j = 0; j < p; ++j)
                    if (!(mask >> j & 1))
                        ndp[mask | (1 << j)] =
                            max(ndp[mask | (1 << j)],
                                dp[mask] + s[x][j]);
            }
        dp.swap(ndp);
    }
    cout << dp[M - 1] << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    int V = 1;
    for (int &x : a) {
        cin >> x;
        V = max(V, x);
    }
    vector<int> spf(V + 1);
    for (int i = 2; i <= V; ++i)
        if (!spf[i])
            for (int j = i; j <= V; j += i)
                if (!spf[j])
                    spf[j] = i;
    vector<int> last(V + 1, n), nxt(n + 1, n);
    for (int i = n - 1; i >= 0; --i) {
        nxt[i] = nxt[i + 1];
        int x = a[i];
        while (x > 1) {
            int p = spf[x];
            nxt[i] = min(nxt[i], last[p]);
            last[p] = i;
            while (x % p == 0)
                x /= p;
        }
    }
    int K = 1;
    while ((1 << K) <= n)
        ++K;
    vector<vector<int>> up(K, vector<int>(n + 1, n));
    up[0] = nxt;
    for (int k = 1; k < K; ++k)
        for (int i = 0; i <= n; ++i)
            up[k][i] = up[k - 1][up[k - 1][i]];
    while (q--) {
        int l, r;
        cin >> l >> r;
        --l;
        --r;
        int ans = 1;
        for (int k = K - 1; k >= 0; --k)
            if (up[k][l] <= r) {
                ans += 1 << k;
                l = up[k][l];
            }
        cout << ans << '\n';
    }
}

