#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    cin >> q;
    struct Op {
        string t;
        int x, y;
    };
    vector<Op> ops(q);
    vector<int> xs;
    for (auto &o : ops) {
        cin >> o.t >> o.x >> o.y;
        xs.push_back(o.x);
    }
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    int n = xs.size();
    vector<set<int>> ys(n);
    vector<int> mx(4 * n, -1);
    function<void(int, int, int, int)> upd = [&](int p, int l,
                                                 int r, int x) {
        if (l == r) {
            mx[p] = ys[x].empty() ? -1 : *ys[x].rbegin();
            return;
        }
        int m = (l + r) / 2;
        if (x <= m)
            upd(p * 2, l, m, x);
        else
            upd(p * 2 + 1, m + 1, r, x);
        mx[p] = max(mx[p * 2], mx[p * 2 + 1]);
    };
    function<int(int, int, int, int, int)> find =
        [&](int p, int l, int r, int L, int y) {
            if (r < L || mx[p] <= y)
                return -1;
            if (l == r)
                return l;
            int m = (l + r) / 2;
            int a = find(p * 2, l, m, L, y);
            return a < 0 ? find(p * 2 + 1, m + 1, r, L, y) : a;
        };
    for (auto o : ops) {
        int x =
            lower_bound(xs.begin(), xs.end(), o.x) - xs.begin();
        if (o.t == "add") {
            ys[x].insert(o.y);
            upd(1, 0, n - 1, x);
        } else if (o.t == "remove") {
            ys[x].erase(o.y);
            upd(1, 0, n - 1, x);
        } else {
            int L = upper_bound(xs.begin(), xs.end(), o.x) -
                    xs.begin();
            int j = find(1, 0, n - 1, L, o.y);
            if (j < 0)
                cout << -1 << '\n';
            else
                cout << xs[j] << ' ' << *ys[j].upper_bound(o.y)
                     << '\n';
        }
    }
}

