struct Euler {
    vector<int> tin, tout, par, depth, order, sz;
    Euler(const vector<vector<int>> &g, int root = 1)
        : tin(g.size()), tout(g.size()), par(g.size(), -1),
          depth(g.size()), sz(g.size(), 1) {
        vector<int> st{root};
        par[root] = root;
        depth[root] = root == 0 ? 0 : 1;
        while (!st.empty()) {
            int u = st.back();
            st.pop_back();
            tin[u] = order.size();
            order.push_back(u);
            for (int v : g[u])
                if (v != par[u]) {
                    par[v] = u;
                    depth[v] = depth[u] + 1;
                    st.push_back(v);
                }
        }
        for (int i = (int)order.size() - 1; i >= 0; --i) {
            int u = order[i];
            tout[u] = tin[u] + sz[u] - 1;
            if (u != root)
                sz[par[u]] += sz[u];
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> g(n + 1);
    for (int v = 1, p; v <= n; ++v) {
        cin >> p;
        g[p].push_back(v);
        g[v].push_back(p);
    }
    Euler e(g, 0);
    int K = 1;
    while ((1 << K) <= n)
        ++K;
    vector<vector<int>> up(K, vector<int>(n + 1));
    for (int v = 1; v <= n; ++v)
        up[0][v] = e.par[v];
    for (int k = 1; k < K; ++k)
        for (int v = 1; v <= n; ++v)
            up[k][v] = up[k - 1][up[k - 1][v]];
    vector<vector<int>> at(n + 1);
    for (int u : e.order)
        at[e.depth[u]].push_back(e.tin[u]);
    int q;
    cin >> q;
    while (q--) {
        int v, p;
        cin >> v >> p;
        int u = v;
        if (p >= e.depth[v])
            u = 0;
        else
            for (int k = 0; k < K; ++k)
                if (p >> k & 1)
                    u = up[k][u];
        if (!u) {
            cout << 0 << ' ';
            continue;
        }
        auto &a = at[e.depth[v]];
        int count = upper_bound(a.begin(), a.end(), e.tout[u]) -
                    lower_bound(a.begin(), a.end(), e.tin[u]);
        cout << count - 1 << ' ';
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a)
        cin >> x;
    vector<array<int, 20>> cnt(4 * n);
    vector<int> lazy(4 * n);
    auto pull = [&](int p) {
        for (int b = 0; b < 20; ++b)
            cnt[p][b] = cnt[p * 2][b] + cnt[p * 2 + 1][b];
    };
    function<void(int, int, int)> build = [&](int p, int l,
                                              int r) {
        if (l == r) {
            for (int b = 0; b < 20; ++b)
                cnt[p][b] = a[l] >> b & 1;
            return;
        }
        int m = (l + r) / 2;
        build(p * 2, l, m);
        build(p * 2 + 1, m + 1, r);
        pull(p);
    };
    build(1, 0, n - 1);
    auto apply = [&](int p, int len, int x) {
        for (int b = 0; b < 20; ++b)
            if (x >> b & 1)
                cnt[p][b] = len - cnt[p][b];
        lazy[p] ^= x;
    };
    auto push = [&](int p, int l, int r) {
        if (lazy[p]) {
            int m = (l + r) / 2;
            apply(p * 2, m - l + 1, lazy[p]);
            apply(p * 2 + 1, r - m, lazy[p]);
            lazy[p] = 0;
        }
    };
    function<void(int, int, int, int, int, int)> upd =
        [&](int p, int l, int r, int L, int R, int x) {
            if (R < l || r < L)
                return;
            if (L <= l && r <= R) {
                apply(p, r - l + 1, x);
                return;
            }
            push(p, l, r);
            int m = (l + r) / 2;
            upd(p * 2, l, m, L, R, x);
            upd(p * 2 + 1, m + 1, r, L, R, x);
            pull(p);
        };
    function<long long(int, int, int, int, int)> sum =
        [&](int p, int l, int r, int L, int R) -> long long {
        if (R < l || r < L)
            return 0;
        if (L <= l && r <= R) {
            long long s = 0;
            for (int b = 0; b < 20; ++b)
                s += cnt[p][b] * (1LL << b);
            return s;
        }
        push(p, l, r);
        int m = (l + r) / 2;
        return sum(p * 2, l, m, L, R) +
               sum(p * 2 + 1, m + 1, r, L, R);
    };
    int q;
    cin >> q;
    while (q--) {
        int t, l, r;
        cin >> t >> l >> r;
        --l;
        --r;
        if (t == 1)
            cout << sum(1, 0, n - 1, l, r) << '\n';
        else {
            int x;
            cin >> x;
            upd(1, 0, n - 1, l, r, x);
        }
    }
}

