struct Euler {
    vector<int> tin, tout, par, depth, order, sz;
    Euler(const vector<vector<int>> &g, int root = 1)
        : tin(g.size()), tout(g.size()), par(g.size(), -1),
          depth(g.size()), sz(g.size(), 1) {
        vector<int> st{root};
        par[root] = root;
        depth[root] = root == 0 ? 0 : 1;
        while (!st.empty()) {
            int u = st.back();
            st.pop_back();
            tin[u] = order.size();
            order.push_back(u);
            for (int v : g[u])
                if (v != par[u]) {
                    par[v] = u;
                    depth[v] = depth[u] + 1;
                    st.push_back(v);
                }
        }
        for (int i = (int)order.size() - 1; i >= 0; --i) {
            int u = order[i];
            tout[u] = tin[u] + sz[u] - 1;
            if (u != root)
                sz[par[u]] += sz[u];
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> g(n + 1);
    for (int i = 1, u, v; i < n; ++i) {
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    Euler e(g);
    vector<int> fill(4 * n), empty(4 * n);
    function<void(int, int, int, int, int, int)> water =
        [&](int p, int l, int r, int L, int R, int t) {
            if (R < l || r < L)
                return;
            if (L <= l && r <= R) {
                fill[p] = max(fill[p], t);
                return;
            }
            int m = (l + r) / 2;
            water(p * 2, l, m, L, R, t);
            water(p * 2 + 1, m + 1, r, L, R, t);
        };
    function<int(int, int, int, int)> wet = [&](int p, int l,
                                                int r, int x) {
        if (l == r)
            return fill[p];
        int m = (l + r) / 2;
        return max(fill[p], x <= m
                                ? wet(p * 2, l, m, x)
                                : wet(p * 2 + 1, m + 1, r, x));
    };
    function<void(int, int, int, int, int)> dry =
        [&](int p, int l, int r, int x, int t) {
            empty[p] = max(empty[p], t);
            if (l == r)
                return;
            int m = (l + r) / 2;
            if (x <= m)
                dry(p * 2, l, m, x, t);
            else
                dry(p * 2 + 1, m + 1, r, x, t);
        };
    function<int(int, int, int, int, int)> last =
        [&](int p, int l, int r, int L, int R) {
            if (R < l || r < L)
                return 0;
            if (L <= l && r <= R)
                return empty[p];
            int m = (l + r) / 2;
            return max(last(p * 2, l, m, L, R),
                       last(p * 2 + 1, m + 1, r, L, R));
        };
    int q;
    cin >> q;
    for (int t = 1; t <= q; ++t) {
        int op, u;
        cin >> op >> u;
        int l = e.tin[u], r = e.tout[u];
        if (op == 1)
            water(1, 0, n - 1, l, r, t);
        else if (op == 2)
            dry(1, 0, n - 1, l, t);
        else
            cout << (wet(1, 0, n - 1, l) >
                     last(1, 0, n - 1, l, r))
                 << '\n';
    }
}

