struct BIT {
    int n;
    vector<long long> t;
    BIT(int n) : n(n), t(n + 2) {}
    void add(int x, long long v) {
        for (++x; x <= n; x += x & -x)
            t[x] += v;
    }
    long long sum(int x) {
        long long s = 0;
        for (++x; x > 0; x -= x & -x)
            s += t[x];
        return s;
    }
};

