int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    vector<long long> sum(4 * n);
    vector<int> mx(4 * n);
    auto pull = [&](int p) {
        sum[p] = sum[p * 2] + sum[p * 2 + 1];
        mx[p] = max(mx[p * 2], mx[p * 2 + 1]);
    };
    function<void(int, int, int, int, int)> set =
        [&](int p, int l, int r, int x, int v) {
            if (l == r) {
                sum[p] = mx[p] = v;
                return;
            }
            int m = (l + r) / 2;
            if (x <= m)
                set(p * 2, l, m, x, v);
            else
                set(p * 2 + 1, m + 1, r, x, v);
            pull(p);
        };
    for (int i = 0, x; i < n; ++i) {
        cin >> x;
        set(1, 0, n - 1, i, x);
    }
    function<void(int, int, int, int, int, int)> mod =
        [&](int p, int l, int r, int L, int R, int v) {
            if (R < l || r < L || mx[p] < v)
                return;
            if (l == r) {
                sum[p] = mx[p] %= v;
                return;
            }
            int m = (l + r) / 2;
            mod(p * 2, l, m, L, R, v);
            mod(p * 2 + 1, m + 1, r, L, R, v);
            pull(p);
        };
    function<long long(int, int, int, int, int)> get =
        [&](int p, int l, int r, int L, int R) -> long long {
        if (R < l || r < L)
            return 0;
        if (L <= l && r <= R)
            return sum[p];
        int m = (l + r) / 2;
        return get(p * 2, l, m, L, R) +
               get(p * 2 + 1, m + 1, r, L, R);
    };
    while (q--) {
        int t, l, r;
        cin >> t >> l >> r;
        if (t == 1)
            cout << get(1, 0, n - 1, l - 1, r - 1) << '\n';
        else if (t == 2) {
            int x;
            cin >> x;
            mod(1, 0, n - 1, l - 1, r - 1, x);
        } else
            set(1, 0, n - 1, l - 1, r);
    }
}

