int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int MOD = 1000000007, S = 1 << 20;
    int n;
    cin >> n;
    vector<int> cnt(S), pow2(n + 1, 1);
    for (int i = 0, x; i < n; ++i) {
        cin >> x;
        ++cnt[x];
    }
    for (int b = 0; b < 20; ++b)
        for (int mask = 0; mask < S; ++mask)
            if (!(mask >> b & 1))
                cnt[mask] += cnt[mask | (1 << b)];
    for (int i = 1; i <= n; ++i)
        pow2[i] = pow2[i - 1] * 2LL % MOD;
    vector<unsigned char> parity(S);
    long long ans = 0;
    for (int mask = 0; mask < S; ++mask) {
        if (mask)
            parity[mask] = parity[mask >> 1] ^ (mask & 1);
        int ways = pow2[cnt[mask]] - 1;
        ans += (parity[mask] ? -ways : ways);
        ans %= MOD;
    }
    cout << (ans + MOD) % MOD << '\n';
}

