struct DSU {
    vector<int> p, sz;
    DSU(int n) : p(n), sz(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (x != p[x]) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    int join(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y)
            return x;
        if (sz[x] < sz[y])
            swap(x, y);
        p[y] = x;
        sz[x] += sz[y];
        return x;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    cin >> n >> m >> q;
    DSU ds(n);
    vector<vector<int>> g(n);
    for (int i = 0, u, v; i < m; ++i) {
        cin >> u >> v;
        --u;
        --v;
        g[u].push_back(v);
        g[v].push_back(u);
        ds.join(u, v);
    }
    vector<int> diam(n), seen(n), dist(n);
    int stamp = 0;
    auto far = [&](int root) {
        ++stamp;
        queue<int> que;
        que.push(root);
        seen[root] = stamp;
        dist[root] = 0;
        int best = root;
        while (!que.empty()) {
            int u = que.front();
            que.pop();
            if (dist[u] > dist[best])
                best = u;
            for (int v : g[u])
                if (seen[v] != stamp) {
                    seen[v] = stamp;
                    dist[v] = dist[u] + 1;
                    que.push(v);
                }
        }
        return pair<int, int>{best, dist[best]};
    };
    for (int i = 0; i < n; ++i)
        if (ds.find(i) == i)
            diam[i] = far(far(i).first).second;
    while (q--) {
        int t, x, y;
        cin >> t >> x;
        --x;
        x = ds.find(x);
        if (t == 1) {
            cout << diam[x] << '\n';
            continue;
        }
        cin >> y;
        --y;
        y = ds.find(y);
        if (x == y)
            continue;
        int d =
            max({diam[x], diam[y],
                 (diam[x] + 1) / 2 + (diam[y] + 1) / 2 + 1});
        int root = ds.join(x, y);
        diam[root] = d;
    }
}

