        if (it == tail.end())
            tail.push_back(a[i]);
        else
            *it = a[i];
    }
    int best = tail.size();
    tail.clear();
    for (int i = n - 1; i >= 0; --i) {
        long long x = -a[i];
        auto it = lower_bound(tail.begin(), tail.end(), x);
        R[i] = it - tail.begin() + 1;
        if (it == tail.end())
            tail.push_back(x);
        else
            *it = x;
    }
    vector<int> count(best + 1);
    for (int i = 0; i < n; ++i)
        if (L[i] + R[i] - 1 == best)
            ++count[L[i]];
    for (int i = 0; i < n; ++i)
        cout << (L[i] + R[i] - 1 != best ? 1
                 : count[L[i]] == 1      ? 3
                                         : 2);
    cout << '\n';
}

#include <bits/stdc++.h>
using namespace std;

struct Range {
    int n;
    vector<long long> mn, mx, lazy;
    Range(vector<long long> a)
        : n(a.size()), mn(4 * n), mx(4 * n), lazy(4 * n) {
        build(1, 0, n - 1, a);
    }
    void pull(int p) {
        mn[p] = min(mn[p * 2], mn[p * 2 + 1]);
        mx[p] = max(mx[p * 2], mx[p * 2 + 1]);
    }
    void apply(int p, long long v) {
        mn[p] += v;
        mx[p] += v;
        lazy[p] += v;
    }
    void push(int p) {
        if (lazy[p]) {
            apply(p * 2, lazy[p]);
            apply(p * 2 + 1, lazy[p]);
            lazy[p] = 0;
        }
    }
    void build(int p, int l, int r, vector<long long> &a) {
        if (l == r) {
            mn[p] = mx[p] = a[l];
            return;
        }
        int m = (l + r) / 2;
        build(p * 2, l, m, a);
        build(p * 2 + 1, m + 1, r, a);
        pull(p);
    }
    void add(int p, int l, int r, int L, int R, long long v) {
        if (R < l || r < L)
            return;
        if (L <= l && r <= R) {
            apply(p, v);
            return;
        }
        push(p);
        int m = (l + r) / 2;
        add(p * 2, l, m, L, R, v);
        add(p * 2 + 1, m + 1, r, L, R, v);
        pull(p);
    }
    long long get(int p, int l, int r, int L, int R) {
        if (R < l || r < L)
            return LLONG_MAX;
        if (L <= l && r <= R)
            return mn[p];
        push(p);
        int m = (l + r) / 2;
        return min(get(p * 2, l, m, L, R),
                   get(p * 2 + 1, m + 1, r, L, R));
    }
    void add(int l, int r, long long v) {
        add(1, 0, n - 1, l, r, v);
    }
    long long get(int l, int r) {
        return get(1, 0, n - 1, l, r);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    Range seg(a);
    int q;
    cin >> q;
    string line;
    getline(cin, line);
    while (q) {
        getline(cin, line);
        istringstream in(line);
        vector<long long> v;
        long long x;
        while (in >> x)
            v.push_back(x);
        if (v.empty())
            continue;
        --q;
        int l = v[0], r = v[1];
        if (v.size() == 3) {
            if (l <= r)
                seg.add(l, r, v[2]);
            else {
                seg.add(l, n - 1, v[2]);
                seg.add(0, r, v[2]);
            }
        } else
            cout << (l <= r ? seg.get(l, r)
                            : min(seg.get(l, n - 1),
                                  seg.get(0, r)))
                 << '\n';
    }
}

