int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<int> divs;
    vector<int> idx(2521);
    for (int x = 1; x <= 2520; ++x)
        if (2520 % x == 0) {
            idx[x] = divs.size();
            divs.push_back(x);
        }
    int S = divs.size();
    vector<array<int, 10>> go(S);
    for (int i = 0; i < S; ++i)
        for (int d = 0; d <= 9; ++d)
            go[i][d] = d ? idx[lcm(divs[i], d)] : i;
    vector<long long> memo(20 * 2520 * S, -1);
    auto count = [&](long long x) {
        if (x < 0)
            return 0LL;
        string s = to_string(x);
        function<long long(int, int, int, bool)> dfs =
            [&](int p, int r, int z, bool tight) -> long long {
            if (p == (int)s.size())
                return r % divs[z] == 0;
            int rem = s.size() - p;
            long long &cache = memo[(rem * 2520 + r) * S + z];
            if (!tight && cache != -1)
                return cache;
            long long ans = 0;
            int lim = tight ? s[p] - '0' : 9;
            for (int d = 0; d <= lim; ++d)
                ans += dfs(p + 1, (r * 10 + d) % 2520, go[z][d],
                           tight && d == lim);
            if (!tight)
                cache = ans;
            return ans;
        };
        return dfs(0, 0, idx[1], true);
    };
    int T;
    cin >> T;
    while (T--) {
        long long l, r;
        cin >> l >> r;
        cout << count(r) - count(l - 1) << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;

struct Euler {
    vector<int> tin, tout, par, depth, order, sz;
    Euler(const vector<vector<int>> &g, int root = 1)
        : tin(g.size()), tout(g.size()), par(g.size(), -1),
          depth(g.size()), sz(g.size(), 1) {
        vector<int> st{root};
        par[root] = root;
        depth[root] = root == 0 ? 0 : 1;
        while (!st.empty()) {
            int u = st.back();
            st.pop_back();
            tin[u] = order.size();
            order.push_back(u);
            for (int v : g[u])
                if (v != par[u]) {
                    par[v] = u;
                    depth[v] = depth[u] + 1;
                    st.push_back(v);
                }
        }
        for (int i = (int)order.size() - 1; i >= 0; --i) {
            int u = order[i];
            tout[u] = tin[u] + sz[u] - 1;
            if (u != root)
                sz[par[u]] += sz[u];
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);
    for (int v = 2, p; v <= n; ++v) {
        cin >> p;
        g[p].push_back(v);
        g[v].push_back(p);
    }
    string s;
    cin >> s;
    Euler e(g);
    vector<vector<int>> at(n + 2), px(n + 2);
    for (int u : e.order) {
        int d = e.depth[u];
        at[d].push_back(e.tin[u]);
        if (px[d].empty())
            px[d].push_back(0);
        px[d].push_back(px[d].back() ^ (1 << (s[u - 1] - 'a')));
    }
    while (m--) {
        int v, h;
        cin >> v >> h;
        if (h > n || at[h].empty()) {
            cout << "Yes\n";
            continue;
        }
        int l = lower_bound(at[h].begin(), at[h].end(),
                            e.tin[v]) -
                at[h].begin(),
            r = upper_bound(at[h].begin(), at[h].end(),
                            e.tout[v]) -
                at[h].begin();
        int mask = px[h][r] ^ px[h][l];
        cout << ((mask & (mask - 1)) ? "No" : "Yes") << '\n';
    }
}

