        cin >> u >> v;
        --u;
        --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    vector<int> par(n, -1), order{0};
    par[0] = 0;
    for (int i = 0; i < n; ++i)
        for (int v : g[order[i]])
            if (v != par[order[i]]) {
                par[v] = order[i];
                order.push_back(v);
            }
    vector<map<int, int>> bag(n);
    vector<int> mx(n);
    vector<long long> sum(n), ans(n);
