    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> c(n + 1);
    for (int i = 1; i <= n; ++i)
        cin >> c[i];
    vector<vector<int>> g(n + 1);
    for (int i = 1, u, v; i < n; ++i) {
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    Euler e(g);
    using U = unsigned long long;
    vector<U> tree(4 * n), lazy(4 * n);
    auto apply = [&](int p, U x) { tree[p] = lazy[p] = x; };
    auto push = [&](int p) {
        if (lazy[p]) {
            apply(p * 2, lazy[p]);
            apply(p * 2 + 1, lazy[p]);
            lazy[p] = 0;
        }
    };
    function<void(int, int, int, int, int, U)> set =
        [&](int p, int l, int r, int L, int R, U x) {
            if (R < l || r < L)
                return;
            if (L <= l && r <= R) {
                apply(p, x);
                return;
            }
            push(p);
            int mid = (l + r) / 2;
            set(p * 2, l, mid, L, R, x);
            set(p * 2 + 1, mid + 1, r, L, R, x);
            tree[p] = tree[p * 2] | tree[p * 2 + 1];
        };
    function<U(int, int, int, int, int)> get =
        [&](int p, int l, int r, int L, int R) -> U {
        if (R < l || r < L)
            return 0;
        if (L <= l && r <= R)
            return tree[p];
        push(p);
        int mid = (l + r) / 2;
        return get(p * 2, l, mid, L, R) |
               get(p * 2 + 1, mid + 1, r, L, R);
    };
    for (int u = 1; u <= n; ++u)
        set(1, 0, n - 1, e.tin[u], e.tin[u], 1ULL << c[u]);
    while (m--) {
        int t, u;
