            set(1, 0, n - 1, e.tin[u], e.tout[u],
                1ULL << color);
        } else {
            U x = get(1, 0, n - 1, e.tin[u], e.tout[u]);
            int count = 0;
            while (x) {
                x &= x - 1;
                ++count;
            }
            cout << count << '\n';
        }
    }
}

