// Standalone C++17; input n,k and values in [1,n].
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int &x : a)
        cin >> x;
    vector<int> f(n + 1);
    int L = 0, R = -1;
    long long cost = 0, INF = (1LL << 60);
    auto add = [&](int i) { cost += f[a[i]]++; };
    auto del = [&](int i) { cost -= --f[a[i]]; };
    auto query = [&](int l, int r) {
        while (L > l)
            add(--L);
        while (R < r)
            add(++R);
        while (L < l)
            del(L++);
        while (R > r)
            del(R--);
        return cost;
    };
    vector<long long> prev(n + 1, INF), cur(n + 1, INF);
    prev[0] = 0;
    for (int t = 1; t <= k; ++t) {
        fill(cur.begin(), cur.end(), INF);
        function<void(int, int, int, int)> solve =
            [&](int l, int r, int ol, int orr) {
                if (l > r)
                    return;
                int m = (l + r) / 2, best = -1;
                for (int j = ol; j <= min(m - 1, orr); ++j) {
                    long long v = prev[j] + query(j, m - 1);
                    if (v < cur[m]) {
                        cur[m] = v;
                        best = j;
                    }
                }
                solve(l, m - 1, ol, best);
                solve(m + 1, r, best, orr);
            };
        solve(t, n, t - 1, n - 1);
        prev.swap(cur);
    }
    cout << prev[n];
}

