    for (int x = 1; x <= 70; ++x)
        if (cnt[x]) {
            int mask = 0, v = x;
            for (int j = 0; j < (int)prime.size(); ++j)
                while (v % prime[j] == 0) {
                    mask ^= 1 << j;
                    v /= prime[j];
                }
            long long ways = pow2[cnt[x] - 1];
            for (int s = 0; s < S; ++s)
                ndp[s] =
                    (dp[s] + 0LL + dp[s ^ mask]) * ways % MOD;
