vector<int> twoSum(vector<int> &a, int target) {
    unordered_map<int, int> seen;
    for (int i = 0; i < (int)a.size(); ++i) {
        auto it = seen.find(target - a[i]);
        if (it != seen.end())
            return {it->second, i};
        seen[a[i]] = i;
    }
    return {};
}

class Solution {
  public:
    bool isSymmetric(TreeNode *r) {
        if (!r)
            return true;
        queue<pair<TreeNode *, TreeNode *>> q;
        q.push({r->left, r->right});
        while (!q.empty()) {
            auto [a, b] = q.front();
            q.pop();
            if (!a || !b) {
                if (a != b)
                    return false;
                continue;
            }
            if (a->val != b->val)
                return false;
            q.push({a->left, b->right});
            q.push({a->right, b->left});
        }
        return true;
    }
};

vector<vector<int>> levelOrder(TreeNode *root) {
    vector<vector<int>> out;
    if (!root)
        return out;
    queue<TreeNode *> q;
    q.push(root);
    while (!q.empty()) {
        int size = q.size();
        vector<int> row;
        while (size--) {
            auto u = q.front();
            q.pop();
            row.push_back(u->val);
            if (u->left)
                q.push(u->left);
            if (u->right)
                q.push(u->right);
        }
        out.push_back(row);
    }
    return out;
}

class Solution {
