            int n = q.size();
            ++d;
            while (n--) {
                auto p = q.front();
                q.pop();
                if (p->left)
                    q.push(p->left);
                if (p->right)
                    q.push(p->right);
            }
        }
        return d;
    }
};

class Solution {
