        if (l >= r)
            return nullptr;
        int x = pre[at++], m = pos[x];
        auto root = new TreeNode(x);
        root->left = build(pre, l, m);
        root->right = build(pre, m + 1, r);
        return root;
    }

  public:
    TreeNode *buildTree(vector<int> &pre, vector<int> &in) {
        pos.clear();
        at = 0;
        for (int i = 0; i < (int)in.size(); ++i)
            pos[in[i]] = i;
