int longestCommonSubsequence(string a, string b) {
    int n = a.size(), m = b.size();
    vector<vector<int>> d(n + 1, vector<int>(m + 1));
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j)
            d[i][j] = a[i - 1] == b[j - 1]
                          ? d[i - 1][j - 1] + 1
                          : max(d[i - 1][j], d[i][j - 1]);
    return d[n][m];
}

