class Solution {
  public:
    int maxPathSum(TreeNode *r) {
        vector<TreeNode *> v{r};
        for (size_t i = 0; i < v.size(); ++i) {
            if (v[i]->left)
                v.push_back(v[i]->left);
            if (v[i]->right)
                v.push_back(v[i]->right);
        }
        unordered_map<TreeNode *, int> g;
        g[nullptr] = 0;
        int ans = INT_MIN;
        for (int i = (int)v.size() - 1; i >= 0; --i) {
            auto p = v[i];
            int l = max(0, g[p->left]),
                rr = max(0, g[p->right]);
            ans = max(ans, p->val + l + rr);
            g[p] = p->val + max(l, rr);
        }
        return ans;
    }
};

class Solution {
