            if (!st.count(x - 1)) {
                long long y = x;
                while (st.count(y))
                    ++y;
                best = max(best, int(y - x));
            }
        return best;
    }
};

class Solution {
  public:
    vector<vector<string>> partition(string s) {
        int n = s.size();
        vector<vector<bool>> pal(n, vector<bool>(n));
        for (int i = n - 1; i >= 0; --i)
            for (int j = i; j < n; ++j)
                pal[i][j] = s[i] == s[j] &&
                            (j - i < 2 || pal[i + 1][j - 1]);
        vector<vector<string>> out;
        vector<string> p;
        function<void(int)> dfs = [&](int i) {
            if (i == n) {
                out.push_back(p);
                return;
            }
            for (int j = i; j < n; ++j)
                if (pal[i][j]) {
                    p.push_back(s.substr(i, j - i + 1));
                    dfs(j + 1);
                    p.pop_back();
                }
        };
        dfs(0);
        return out;
    }
};

