class LRUCache {
    int cap;
    list<pair<int, int>> order;
    unordered_map<int, list<pair<int, int>>::iterator> pos;

  public:
    LRUCache(int capacity) : cap(capacity) {}
    int get(int key) {
        auto it = pos.find(key);
        if (it == pos.end())
            return -1;
        order.splice(order.begin(), order, it->second);
        return it->second->second;
    }
    void put(int key, int value) {
        auto it = pos.find(key);
        if (it != pos.end()) {
            it->second->second = value;
            order.splice(order.begin(), order, it->second);
            return;
        }
        if (cap == 0)
            return;
        order.push_front({key, value});
        pos[key] = order.begin();
        if ((int)order.size() > cap) {
            pos.erase(order.back().first);
            order.pop_back();
        }
    }
};

class Solution {
    ListNode *cut(ListNode *h, int n) {
        if (!h)
            return nullptr;
        while (--n && h->next)
            h = h->next;
        auto r = h->next;
        h->next = nullptr;
        return r;
    }

  public:
    ListNode *sortList(ListNode *h) {
        int n = 0;
        for (auto p = h; p; p = p->next)
            ++n;
        ListNode d(0, h);
        for (int w = 1; w < n; w *= 2) {
            auto cur = d.next, tail = &d;
            while (cur) {
                auto a = cur, b = cut(a, w);
                cur = cut(b, w);
                while (a && b) {
                    if (a->val <= b->val) {
                        tail->next = a;
                        a = a->next;
                    } else {
                        tail->next = b;
                        b = b->next;
                    }
                    tail = tail->next;
                }
                tail->next = a ? a : b;
                while (tail->next)
                    tail = tail->next;
            }
        }
        return d.next;
    }
};

class Solution {
  public:
    vector<vector<int>> threeSum(vector<int> &a) {
        sort(a.begin(), a.end());
        vector<vector<int>> out;
        int n = a.size();
        for (int i = 0; i < n; ++i) {
            if (i && a[i] == a[i - 1])
                continue;
            int l = i + 1, r = n - 1;
            while (l < r) {
                long long sum = 0LL + a[i] + a[l] + a[r];
                if (sum < 0)
                    ++l;
                else if (sum > 0)
                    --r;
                else {
                    out.push_back({a[i], a[l], a[r]});
                    int x = a[l], y = a[r];
                    while (l < r && a[l] == x)
                        ++l;
                    while (l < r && a[r] == y)
                        --r;
                }
            }
        }
        return out;
    }
};

class Solution {
