        for (int i = 1; i < (int)a.size(); ++i) {
            int x = a[i], p = hi, q = lo;
            hi = max({x, p * x, q * x});
            lo = min({x, p * x, q * x});
            ans = max(ans, hi);
        }
        return ans;
    }
};

