class Solution {
  public:
    vector<string> letterCombinations(string digits) {
        if (digits.empty())
            return {};
        vector<string> keys = {"",    "",    "abc", "def",
                               "ghi", "jkl", "mno", "pqrs",
                               "tuv", "wxyz"},
                       out;
        string path;
        function<void(int)> dfs = [&](int i) {
            if (i == (int)digits.size()) {
                out.push_back(path);
                return;
            }
            for (char c : keys[digits[i] - '0']) {
                path += c;
                dfs(i + 1);
                path.pop_back();
            }
        };
        dfs(0);
        return out;
    }
};

