int rob(vector<int> &a) {
    int before = 0, previous = 0;
    for (int x : a) {
        int now = max(previous, before + x);
        before = previous;
        previous = now;
    }
    return previous;
}

class Solution {
  public:
    vector<int> rightSideView(TreeNode *r) {
        vector<int> ans;
        if (!r)
            return ans;
        queue<TreeNode *> q;
        q.push(r);
        while (!q.empty()) {
            int n = q.size();
            for (int i = 0; i < n; ++i) {
                auto p = q.front();
                q.pop();
                if (i == n - 1)
                    ans.push_back(p->val);
                if (p->left)
                    q.push(p->left);
                if (p->right)
                    q.push(p->right);
            }
        }
        return ans;
    }
};

class Solution {
  public:
    ListNode *addTwoNumbers(ListNode *a, ListNode *b) {
        ListNode d;
        auto t = &d;
        int carry = 0;
        while (a || b || carry) {
            int sum = carry;
            if (a) {
                sum += a->val;
                a = a->next;
            }
            if (b) {
                sum += b->val;
                b = b->next;
            }
            t->next = new ListNode(sum % 10);
            t = t->next;
            carry = sum / 10;
        }
        return d.next;
    }
};

class Solution {
