        for (char c : s) {
            if (c == '(')
                st.push(')');
            else if (c == '[')
                st.push(']');
            else if (c == '{')
                st.push('}');
            else {
                if (st.empty() || st.top() != c)
                    return false;
                st.pop();
            }
        }
        return st.empty();
    }
};

int numIslands(vector<vector<char>> &g) {
    if (g.empty())
        return 0;
    int n = g.size(), m = g[0].size(), ans = 0;
    int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            if (g[i][j] == '1') {
                ++ans;
                queue<pair<int, int>> q;
                q.push({i, j});
                g[i][j] = '0';
                while (!q.empty()) {
                    auto [x, y] = q.front();
                    q.pop();
                    for (int d = 0; d < 4; ++d) {
                        int a = x + dx[d], b = y + dy[d];
                        if (a >= 0 && a < n && b >= 0 &&
                            b < m && g[a][b] == '1') {
                            g[a][b] = '0';
                            q.push({a, b});
                        }
                    }
                }
            }
    return ans;
}

ListNode *reverseList(ListNode *head) {
