    while (head) {
        auto next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

class Solution {
  public:
    bool canFinish(int n, vector<vector<int>> &prerequisites) {
        vector<vector<int>> g(n);
        vector<int> deg(n);
        for (auto e : prerequisites) {
            g[e[1]].push_back(e[0]);
            ++deg[e[0]];
        }
        queue<int> q;
        for (int i = 0; i < n; ++i)
            if (!deg[i])
                q.push(i);
        int done = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            ++done;
            for (int v : g[u])
                if (--deg[v] == 0)
                    q.push(v);
        }
        return done == n;
    }
};

class Trie {
    struct T {
        array<int, 26> next;
        bool end = false;
        T() { next.fill(-1); }
    };
    vector<T> v;
    int find(const string &s) {
        int u = 0;
        for (char c : s) {
            u = v[u].next[c - 'a'];
            if (u < 0)
                return -1;
        }
        return u;
    }

  public:
    Trie() { v.emplace_back(); }
    void insert(string s) {
        int u = 0;
        for (char c : s) {
            int k = c - 'a';
            if (v[u].next[k] < 0) {
                int id = v.size();
                v[u].next[k] = id;
                v.emplace_back();
            }
            u = v[u].next[k];
        }
        v[u].end = true;
    }
    bool search(string s) {
        int u = find(s);
        return u >= 0 && v[u].end;
    }
    bool startsWith(string s) { return find(s) >= 0; }
};

class Solution {
  public:
    ListNode *mergeTwoLists(ListNode *a, ListNode *b) {
        ListNode dummy;
        auto t = &dummy;
        while (a && b) {
            if (a->val <= b->val) {
                t->next = a;
                a = a->next;
            } else {
                t->next = b;
                b = b->next;
            }
            t = t->next;
        }
        t->next = a ? a : b;
        return dummy.next;
    }
};

