class Solution {
  public:
    vector<string> generateParenthesis(int n) {
        vector<string> out;
        string p;
        function<void(int, int)> dfs = [&](int l, int r) {
            if (r == n) {
                out.push_back(p);
                return;
            }
            if (l < n) {
                p += '(';
                dfs(l + 1, r);
                p.pop_back();
            }
            if (r < l) {
                p += ')';
                dfs(l, r + 1);
                p.pop_back();
            }
        };
        dfs(0, 0);
        return out;
    }
};

class Solution {
  public:
    TreeNode *invertTree(TreeNode *r) {
        if (!r)
            return r;
        stack<TreeNode *> s;
        s.push(r);
        while (!s.empty()) {
            auto p = s.top();
            s.pop();
            swap(p->left, p->right);
            if (p->left)
                s.push(p->left);
            if (p->right)
                s.push(p->right);
        }
        return r;
    }
};

class Solution {
  public:
    ListNode *mergeKLists(vector<ListNode *> &lists) {
        auto cmp = [](ListNode *a, ListNode *b) {
            return a->val > b->val;
        };
        priority_queue<ListNode *, vector<ListNode *>,
                       decltype(cmp)>
            q(cmp);
        for (auto p : lists)
            if (p)
                q.push(p);
        ListNode d;
        auto t = &d;
        while (!q.empty()) {
            auto p = q.top();
            q.pop();
            if (p->next)
                q.push(p->next);
            t->next = p;
            t = p;
        }
        t->next = nullptr;
        return d.next;
    }
};

class Solution {
  public:
    int kthSmallest(TreeNode *r, int k) {
        stack<TreeNode *> st;
        while (r || !st.empty()) {
            while (r) {
                st.push(r);
                r = r->left;
            }
            r = st.top();
            st.pop();
            if (--k == 0)
                return r->val;
            r = r->right;
        }
        return -1;
    }
};

class Solution {
    ListNode *rev(ListNode *p) {
        ListNode *prev = nullptr;
        while (p) {
            auto q = p->next;
            p->next = prev;
            prev = p;
            p = q;
        }
        return prev;
    }

  public:
    bool isPalindrome(ListNode *h) {
        if (!h || !h->next)
            return true;
        auto slow = h, fast = h;
        while (fast->next && fast->next->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        auto tail = rev(slow->next), a = h, b = tail;
        bool ok = true;
        while (b) {
            if (a->val != b->val)
                ok = false;
            a = a->next;
            b = b->next;
        }
        slow->next = rev(tail);
        return ok;
    }
};

class Solution {
  public:
    TreeNode *lowestCommonAncestor(TreeNode *r, TreeNode *p,
                                   TreeNode *q) {
        unordered_map<TreeNode *, TreeNode *> par;
        par[r] = nullptr;
        vector<TreeNode *> st{r};
        while (!par.count(p) || !par.count(q)) {
            auto x = st.back();
            st.pop_back();
            if (x->left) {
                par[x->left] = x;
                st.push_back(x->left);
            }
            if (x->right) {
                par[x->right] = x;
                st.push_back(x->right);
            }
        }
        unordered_set<TreeNode *> seen;
        for (auto x = p; x; x = par[x])
            seen.insert(x);
        for (auto x = q; x; x = par[x])
            if (seen.count(x))
                return x;
        return nullptr;
    }
};

class Solution {
  public:
    vector<int> productExceptSelf(vector<int> &a) {
        int n = a.size();
        vector<int> r(n, 1);
        for (int i = 1; i < n; ++i)
            r[i] = r[i - 1] * a[i - 1];
        int suffix = 1;
        for (int i = n - 1; i >= 0; --i) {
            r[i] *= suffix;
            suffix *= a[i];
        }
        return r;
    }
};

vector<int> maxSlidingWindow(vector<int> &a, int k) {
    deque<int> q;
    vector<int> out;
    for (int i = 0; i < (int)a.size(); ++i) {
        while (!q.empty() && q.front() <= i - k)
            q.pop_front();
        while (!q.empty() && a[q.back()] <= a[i])
            q.pop_back();
        q.push_back(i);
        if (i >= k - 1)
            out.push_back(a[q.front()]);
    }
    return out;
}

class Solution {
  public:
    ListNode *swapPairs(ListNode *h) {
        ListNode d(0, h);
        auto p = &d;
        while (p->next && p->next->next) {
            auto a = p->next, b = a->next;
            a->next = b->next;
            b->next = a;
            p->next = b;
            p = a;
        }
        return d.next;
    }
};

class Solution {
  public:
    bool searchMatrix(vector<vector<int>> &a, int target) {
        if (a.empty() || a[0].empty())
            return false;
        int i = 0, j = a[0].size() - 1;
        while (i < (int)a.size() && j >= 0) {
            if (a[i][j] == target)
                return true;
            if (a[i][j] > target)
                --j;
            else
                ++i;
        }
        return false;
    }
};

class Solution {
  public:
    ListNode *reverseKGroup(ListNode *h, int k) {
        ListNode d(0, h);
        auto before = &d;
        while (true) {
            auto end = before;
            for (int i = 0; i < k && end; ++i)
                end = end->next;
            if (!end)
                break;
            auto after = end->next, cur = before->next,
                 prev = after, old = cur;
            while (cur != after) {
                auto next = cur->next;
                cur->next = prev;
                prev = cur;
                cur = next;
            }
            before->next = end;
            before = old;
        }
        return d.next;
    }
};

class Solution {
  public:
    int numSquares(int n) {
        vector<int> d(n + 1, n + 1);
        d[0] = 0;
        for (int x = 1; x <= n; ++x)
            for (int j = 1; j * j <= x; ++j)
                d[x] = min(d[x], d[x - j * j] + 1);
        return d[n];
    }
};

class Solution {
  public:
    void moveZeroes(vector<int> &a) {
        int w = 0;
        for (int x : a)
            if (x)
                a[w++] = x;
        while (w < (int)a.size())
            a[w++] = 0;
    }
};

class Solution {
  public:
    int findDuplicate(vector<int> &a) {
        int slow = 0, fast = 0;
        do {
            slow = a[slow];
            fast = a[a[fast]];
        } while (slow != fast);
        int p = 0;
        while (p != slow) {
            p = a[p];
            slow = a[slow];
        }
        return p;
    }
};

class MedianFinder {
    priority_queue<int> L;
    priority_queue<int, vector<int>, greater<int>> R;

  public:
    void addNum(int x) {
        L.push(x);
        R.push(L.top());
        L.pop();
        if (L.size() < R.size()) {
            L.push(R.top());
            R.pop();
        }
    }
    double findMedian() {
        return L.size() > R.size()
                   ? L.top()
                   : (double(L.top()) + R.top()) / 2;
    }
};

int lengthOfLongestSubstring(string s) {
    vector<int> last(256, -1);
    int l = 0, best = 0;
    for (int r = 0; r < (int)s.size(); ++r) {
        unsigned char c = s[r];
        l = max(l, last[c] + 1);
        last[c] = r;
        best = max(best, r - l + 1);
    }
    return best;
}

int lengthOfLIS(vector<int> &a) {
    vector<int> tails;
    for (int x : a) {
        auto p = lower_bound(tails.begin(), tails.end(), x);
        if (p == tails.end())
            tails.push_back(x);
        else
            *p = x;
    }
    return tails.size();
}

class Solution {
  public:
    void nextPermutation(vector<int> &a) {
        int i = (int)a.size() - 2;
        while (i >= 0 && a[i] >= a[i + 1])
            --i;
        if (i >= 0) {
            int j = a.size() - 1;
            while (a[j] <= a[i])
                --j;
            swap(a[i], a[j]);
        }
        reverse(a.begin() + i + 1, a.end());
    }
};

class Solution {
  public:
    int longestValidParentheses(string s) {
        vector<int> st{-1};
        int ans = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            if (s[i] == '(')
                st.push_back(i);
            else {
                st.pop_back();
                if (st.empty())
                    st.push_back(i);
                else
                    ans = max(ans, i - st.back());
            }
        }
        return ans;
    }
};

class Solution {
  public:
    int coinChange(vector<int> &c, int amount) {
        vector<int> d(amount + 1, amount + 1);
        d[0] = 0;
        for (int x = 1; x <= amount; ++x)
            for (int v : c)
                if (v <= x)
                    d[x] = min(d[x], d[x - v] + 1);
        return d[amount] > amount ? -1 : d[amount];
    }
};

class Solution {
  public:
    int search(vector<int> &a, int target) {
        int l = 0, r = (int)a.size() - 1;
        while (l <= r) {
            int m = l + (r - l) / 2;
            if (a[m] == target)
                return m;
            if (a[l] <= a[m]) {
                if (a[l] <= target && target < a[m])
                    r = m - 1;
                else
                    l = m + 1;
            } else {
                if (a[m] < target && target <= a[r])
                    l = m + 1;
                else
                    r = m - 1;
            }
        }
        return -1;
    }
};

class Solution {
  public:
    vector<int> searchRange(vector<int> &a, int x) {
        auto l = lower_bound(a.begin(), a.end(), x);
        if (l == a.end() || *l != x)
            return {-1, -1};
        auto r = upper_bound(a.begin(), a.end(), x);
        return {int(l - a.begin()), int(r - a.begin() - 1)};
    }
};

class Solution {
  public:
    vector<int> topKFrequent(vector<int> &a, int k) {
        unordered_map<int, int> cnt;
        for (int x : a)
            ++cnt[x];
        vector<vector<int>> bucket(a.size() + 1);
        for (auto p : cnt)
            bucket[p.second].push_back(p.first);
        vector<int> r;
        for (int f = a.size(); f >= 1; --f)
            for (int x : bucket[f]) {
                r.push_back(x);
                if ((int)r.size() == k)
                    return r;
            }
        return r;
    }
};

int searchInsert(vector<int> &a, int target) {
    int l = 0, r = a.size();
    while (l < r) {
        int m = l + (r - l) / 2;
        if (a[m] < target)
            l = m + 1;
        else
            r = m;
    }
    return l;
}

class Solution {
  public:
    vector<vector<int>> combinationSum(vector<int> &a,
                                       int target) {
        sort(a.begin(), a.end());
        vector<vector<int>> r;
        vector<int> p;
        function<void(int, int)> dfs = [&](int start, int rem) {
            if (!rem) {
                r.push_back(p);
                return;
            }
            for (int i = start;
                 i < (int)a.size() && a[i] <= rem; ++i) {
                p.push_back(a[i]);
                dfs(i, rem - a[i]);
                p.pop_back();
            }
        };
        dfs(0, target);
        return r;
    }
};

class Solution {
  public:
    string decodeString(string s) {
        vector<pair<string, int>> st;
        string cur;
        int k = 0;
        for (char c : s) {
            if (c >= '0' && c <= '9')
                k = k * 10 + c - '0';
            else if (c == '[') {
                st.push_back({cur, k});
                cur.clear();
                k = 0;
            } else if (c == ']') {
                auto [prefix, times] = st.back();
                st.pop_back();
                string next = prefix;
                while (times--)
                    next += cur;
                cur = move(next);
            } else
                cur += c;
        }
        return cur;
    }
};

class Solution {
  public:
    double findMedianSortedArrays(vector<int> &a,
                                  vector<int> &b) {
        if (a.size() > b.size())
            return findMedianSortedArrays(b, a);
        int m = a.size(), n = b.size(), l = 0, r = m;
        while (l <= r) {
            int i = (l + r) / 2, j = (m + n + 1) / 2 - i;
            int al = i ? a[i - 1] : INT_MIN,
                ar = i < m ? a[i] : INT_MAX,
                bl = j ? b[j - 1] : INT_MIN,
                br = j < n ? b[j] : INT_MAX;
            if (al <= br && bl <= ar) {
                if ((m + n) % 2)
                    return max(al, bl);
                return (double(max(al, bl)) + min(ar, br)) / 2;
            }
            if (al > br)
                r = i - 1;
            else
                l = i + 1;
        }
        return 0;
    }
};

class Solution {
  public:
    int firstMissingPositive(vector<int> &a) {
        int n = a.size();
        for (int i = 0; i < n; ++i)
            while (a[i] >= 1 && a[i] <= n &&
                   a[a[i] - 1] != a[i])
                swap(a[i], a[a[i] - 1]);
        for (int i = 0; i < n; ++i)
            if (a[i] != i + 1)
                return i + 1;
        return n + 1;
    }
};

class Solution {
  public:
    bool canPartition(vector<int> &a) {
        int sum = accumulate(a.begin(), a.end(), 0);
        if (sum % 2)
            return false;
        int t = sum / 2;
        vector<bool> d(t + 1);
        d[0] = true;
        for (int x : a)
            for (int s = t; s >= x; --s)
                d[s] = d[s] || d[s - x];
        return d[t];
    }
};

class Solution {
  public:
    int trap(vector<int> &h) {
        int n = h.size();
        if (!n)
            return 0;
        vector<int> L(n), R(n);
        L[0] = h[0];
        R[n - 1] = h[n - 1];
        for (int i = 1; i < n; ++i)
            L[i] = max(L[i - 1], h[i]);
        for (int i = n - 2; i >= 0; --i)
            R[i] = max(R[i + 1], h[i]);
        int ans = 0;
        for (int i = 0; i < n; ++i)
            ans += min(L[i], R[i]) - h[i];
        return ans;
    }
};

class Solution {
    unordered_map<long long, int> cnt;
    long long target;
    int ans;
    void dfs(TreeNode *p, long long sum) {
        if (!p)
            return;
        sum += p->val;
        ans += cnt[sum - target];
        ++cnt[sum];
        dfs(p->left, sum);
        dfs(p->right, sum);
        --cnt[sum];
    }

  public:
    int pathSum(TreeNode *r, int t) {
        cnt.clear();
        cnt[0] = 1;
        target = t;
        ans = 0;
        dfs(r, 0);
        return ans;
    }
};

class Solution {
  public:
    vector<int> findAnagrams(string s, string p) {
        array<int, 26> w{}, need{};
        vector<int> ans;
        int m = p.size();
        if (!m)
            return ans;
        for (char c : p)
            ++need[c - 'a'];
        for (int i = 0; i < (int)s.size(); ++i) {
            ++w[s[i] - 'a'];
            if (i >= m)
                --w[s[i - m] - 'a'];
            if (i + 1 >= m && w == need)
                ans.push_back(i - m + 1);
        }
        return ans;
    }
};

class Solution {
  public:
    int jump(vector<int> &a) {
        int end = 0, far = 0, steps = 0;
        for (int i = 0; i + 1 < (int)a.size(); ++i) {
            far = max(far, i + a[i]);
            if (i == end) {
                ++steps;
                end = far;
            }
        }
        return steps;
    }
};

vector<vector<int>> permute(vector<int> &a) {
    vector<vector<int>> out;
    vector<int> path, used(a.size());
    function<void()> dfs = [&] {
        if (path.size() == a.size()) {
            out.push_back(path);
            return;
        }
        for (int i = 0; i < (int)a.size(); ++i)
            if (!used[i]) {
                used[i] = 1;
                path.push_back(a[i]);
                dfs();
                path.pop_back();
                used[i] = 0;
            }
    };
    dfs();
    return out;
}

class Solution {
  public:
    void rotate(vector<vector<int>> &a) {
        int n = a.size();
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j < n; ++j)
                swap(a[i][j], a[j][i]);
        for (auto &r : a)
            reverse(r.begin(), r.end());
    }
};

class Solution {
  public:
    vector<vector<string>> groupAnagrams(vector<string> &a) {
        unordered_map<string, vector<string>> m;
        for (auto s : a) {
            auto key = s;
            sort(key.begin(), key.end());
            m[key].push_back(s);
        }
        vector<vector<string>> r;
        for (auto &p : m)
            r.push_back(p.second);
        return r;
    }
};

class Solution {
  public:
    string longestPalindrome(string s) {
        int start = 0, best = 0;
        auto expand = [&](int l, int r) {
            while (l >= 0 && r < (int)s.size() &&
                   s[l] == s[r]) {
                if (r - l + 1 > best) {
                    best = r - l + 1;
                    start = l;
                }
                --l;
                ++r;
            }
        };
        for (int i = 0; i < (int)s.size(); ++i) {
            expand(i, i);
            expand(i, i + 1);
        }
        return s.substr(start, best);
    }
};

class Solution {
  public:
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> out;
        vector<string> b(n, string(n, '.'));
        vector<int> col(n), d1(2 * n), d2(2 * n);
        function<void(int)> dfs = [&](int r) {
            if (r == n) {
                out.push_back(b);
                return;
            }
            for (int c = 0; c < n; ++c)
                if (!col[c] && !d1[r + c] && !d2[r - c + n]) {
                    col[c] = d1[r + c] = d2[r - c + n] = 1;
                    b[r][c] = 'Q';
                    dfs(r + 1);
                    b[r][c] = '.';
                    col[c] = d1[r + c] = d2[r - c + n] = 0;
                }
        };
        dfs(0);
        return out;
    }
};

class Solution {
  public:
    int maxSubArray(vector<int> &a) {
        int end = a[0], best = a[0];
        for (int i = 1; i < (int)a.size(); ++i) {
            end = max(a[i], end + a[i]);
            best = max(best, end);
        }
        return best;
    }
};

class Solution {
  public:
    vector<int> spiralOrder(vector<vector<int>> &a) {
        vector<int> r;
        if (a.empty())
            return r;
        int t = 0, b = a.size() - 1, l = 0, h = a[0].size() - 1;
        while (t <= b && l <= h) {
            for (int j = l; j <= h; ++j)
                r.push_back(a[t][j]);
            ++t;
            for (int i = t; i <= b; ++i)
                r.push_back(a[i][h]);
            --h;
            if (t <= b) {
                for (int j = h; j >= l; --j)
                    r.push_back(a[b][j]);
                --b;
            }
            if (l <= h) {
                for (int i = b; i >= t; --i)
                    r.push_back(a[i][l]);
                ++l;
            }
        }
        return r;
    }
};

class Solution {
  public:
    int diameterOfBinaryTree(TreeNode *r) {
        if (!r)
            return 0;
        vector<TreeNode *> v{r};
        for (size_t i = 0; i < v.size(); ++i) {
            if (v[i]->left)
                v.push_back(v[i]->left);
            if (v[i]->right)
                v.push_back(v[i]->right);
        }
        unordered_map<TreeNode *, int> h;
        h[nullptr] = 0;
        int ans = 0;
        for (int i = (int)v.size() - 1; i >= 0; --i) {
            auto p = v[i];
            int l = h[p->left], rr = h[p->right];
            ans = max(ans, l + rr);
            h[p] = 1 + max(l, rr);
        }
        return ans;
    }
};

class Solution {
  public:
    bool canJump(vector<int> &a) {
        int far = 0;
        for (int i = 0; i < (int)a.size(); ++i) {
            if (i > far)
                return false;
            far = max(far, i + a[i]);
            if (far >= (int)a.size() - 1)
                return true;
        }
        return true;
    }
};

class Solution {
  public:
    vector<vector<int>> merge(vector<vector<int>> &a) {
        sort(a.begin(), a.end());
        vector<vector<int>> r;
        for (auto p : a) {
            if (r.empty() || r.back()[1] < p[0])
                r.push_back(p);
            else
                r.back()[1] = max(r.back()[1], p[1]);
        }
        return r;
    }
};

int subarraySum(vector<int> &a, int k) {
    unordered_map<long long, long long> f;
    f[0] = 1;
    long long s = 0, ans = 0;
    for (int x : a) {
        s += x;
        ans += f[s - k];
        ++f[s];
    }
    return (int)ans;
}

class Solution {
  public:
    int uniquePaths(int m, int n) {
        vector<int> d(n, 1);
        for (int i = 1; i < m; ++i)
            for (int j = 1; j < n; ++j)
                d[j] += d[j - 1];
        return d.back();
    }
};

class Solution {
  public:
    int minPathSum(vector<vector<int>> &a) {
        int n = a[0].size();
        vector<int> d(n, INT_MAX);
        for (int i = 0; i < (int)a.size(); ++i)
            for (int j = 0; j < n; ++j) {
                if (i == 0 && j == 0)
                    d[j] = a[i][j];
                else
                    d[j] = min(d[j], j ? d[j - 1] : INT_MAX) +
                           a[i][j];
            }
        return d.back();
    }
};

class Solution {
  public:
    int climbStairs(int n) {
        int a = 1, b = 1;
        for (int i = 2; i <= n; ++i) {
            int c = a + b;
            a = b;
            b = c;
        }
        return b;
    }
};

class Solution {
  public:
    int minDistance(string a, string b) {
        int m = a.size(), n = b.size();
        vector<vector<int>> d(m + 1, vector<int>(n + 1));
        for (int i = 0; i <= m; ++i)
            d[i][0] = i;
        for (int j = 0; j <= n; ++j)
            d[0][j] = j;
        for (int i = 1; i <= m; ++i)
            for (int j = 1; j <= n; ++j)
                d[i][j] =
                    a[i - 1] == b[j - 1]
                        ? d[i - 1][j - 1]
                        : 1 + min({d[i - 1][j], d[i][j - 1],
                                   d[i - 1][j - 1]});
        return d[m][n];
    }
};

class Solution {
  public:
    void setZeroes(vector<vector<int>> &a) {
        int m = a.size(), n = a[0].size();
        bool row = false, col = false;
        for (int j = 0; j < n; ++j)
            row |= a[0][j] == 0;
        for (int i = 0; i < m; ++i)
            col |= a[i][0] == 0;
        for (int i = 1; i < m; ++i)
            for (int j = 1; j < n; ++j)
                if (!a[i][j])
                    a[i][0] = a[0][j] = 0;
        for (int i = 1; i < m; ++i)
            for (int j = 1; j < n; ++j)
                if (!a[i][0] || !a[0][j])
                    a[i][j] = 0;
        if (row)
            fill(a[0].begin(), a[0].end(), 0);
        if (col)
            for (auto &r : a)
                r[0] = 0;
    }
};

class Solution {
  public:
    vector<int> dailyTemperatures(vector<int> &a) {
        vector<int> r(a.size()), st;
        for (int i = 0; i < (int)a.size(); ++i) {
            while (!st.empty() && a[st.back()] < a[i]) {
                int j = st.back();
                st.pop_back();
                r[j] = i - j;
            }
            st.push_back(i);
        }
        return r;
    }
};

class Solution {
  public:
    bool searchMatrix(vector<vector<int>> &a, int target) {
        if (a.empty() || a[0].empty())
            return false;
        int n = a[0].size(), l = 0, r = a.size() * n;
        while (l < r) {
            int m = l + (r - l) / 2;
            if (a[m / n][m % n] < target)
                l = m + 1;
            else
                r = m;
        }
        return l < (int)a.size() * n &&
               a[l / n][l % n] == target;
    }
};

class Solution {
  public:
    void sortColors(vector<int> &a) {
        int l = 0, i = 0, r = (int)a.size() - 1;
        while (i <= r) {
            if (a[i] == 0)
                swap(a[l++], a[i++]);
            else if (a[i] == 2)
                swap(a[i], a[r--]);
            else
                ++i;
        }
    }
};

class Solution {
  public:
    string minWindow(string s, string t) {
        if (t.empty())
            return "";
        vector<int> need(256);
        for (unsigned char c : t)
            ++need[c];
        int missing = t.size(), l = 0, start = 0,
            best = INT_MAX;
        for (int r = 0; r < (int)s.size(); ++r) {
            if (need[(unsigned char)s[r]]-- > 0)
                --missing;
            while (!missing) {
                if (r - l + 1 < best) {
                    best = r - l + 1;
                    start = l;
                }
                if (++need[(unsigned char)s[l++]] > 0)
                    ++missing;
            }
        }
        return best == INT_MAX ? "" : s.substr(start, best);
    }
};

class Solution {
  public:
    vector<int> partitionLabels(string s) {
        array<int, 26> last{};
        for (int i = 0; i < (int)s.size(); ++i)
            last[s[i] - 'a'] = i;
        vector<int> r;
        int start = 0, end = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            end = max(end, last[s[i] - 'a']);
            if (i == end) {
                r.push_back(i - start + 1);
                start = i + 1;
            }
        }
        return r;
    }
};

class Solution {
  public:
    vector<vector<int>> subsets(vector<int> &a) {
        vector<vector<int>> r(1);
        for (int x : a) {
            int n = r.size();
            for (int i = 0; i < n; ++i) {
                auto v = r[i];
                v.push_back(x);
                r.push_back(v);
            }
        }
        return r;
    }
};

class Solution {
  public:
    bool exist(vector<vector<char>> &a, string word) {
        if (word.empty())
            return true;
        int m = a.size(), n = a[0].size();
        function<bool(int, int, int)> dfs = [&](int x, int y,
                                                int i) {
            if (x < 0 || y < 0 || x >= m || y >= n ||
                a[x][y] != word[i])
                return false;
            if (i + 1 == (int)word.size())
                return true;
            char c = a[x][y];
            a[x][y] = '#';
            bool ok =
                dfs(x + 1, y, i + 1) || dfs(x - 1, y, i + 1) ||
                dfs(x, y + 1, i + 1) || dfs(x, y - 1, i + 1);
            a[x][y] = c;
            return ok;
        };
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                if (dfs(i, j, 0))
                    return true;
        return false;
    }
};

class Solution {
  public:
    int largestRectangleArea(vector<int> &a) {
        vector<int> st;
        int ans = 0, n = a.size();
        for (int i = 0; i <= n; ++i) {
            int h = i < n ? a[i] : 0;
            while (!st.empty() && a[st.back()] > h) {
                int height = a[st.back()];
                st.pop_back();
                int left = st.empty() ? -1 : st.back();
                ans = max(ans, height * (i - left - 1));
            }
            if (i < n)
                st.push_back(i);
        }
        return ans;
    }
};

class Solution {
  public:
    vector<int> inorderTraversal(TreeNode *root) {
        vector<int> out;
        stack<TreeNode *> st;
        auto p = root;
        while (p || !st.empty()) {
            while (p) {
                st.push(p);
                p = p->left;
            }
            p = st.top();
            st.pop();
            out.push_back(p->val);
            p = p->right;
        }
        return out;
    }
};

class Solution {
  public:
    bool isValidBST(TreeNode *r) {
        stack<TreeNode *> st;
        long long prev = LLONG_MIN;
        while (r || !st.empty()) {
            while (r) {
                st.push(r);
                r = r->left;
            }
            r = st.top();
            st.pop();
            if (r->val <= prev)
                return false;
            prev = r->val;
            r = r->right;
        }
        return true;
    }
};

class Solution {
  public:
    int orangesRotting(vector<vector<int>> &a) {
        int m = a.size(), n = a[0].size(), fresh = 0, time = 0;
        queue<pair<int, int>> q;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j) {
                if (a[i][j] == 2)
                    q.push({i, j});
                if (a[i][j] == 1)
                    ++fresh;
            }
        int d[5] = {1, 0, -1, 0, 1};
        while (fresh && !q.empty()) {
            int k = q.size();
            ++time;
            while (k--) {
                auto [x, y] = q.front();
                q.pop();
                for (int t = 0; t < 4; ++t) {
                    int u = x + d[t], v = y + d[t + 1];
                    if (u >= 0 && u < m && v >= 0 && v < n &&
                        a[u][v] == 1) {
                        a[u][v] = 2;
                        --fresh;
                        q.push({u, v});
                    }
                }
            }
        }
        return fresh ? -1 : time;
    }
};
